'use strict';
const compressed = Uint8Array.from(atob(document.getElementById('report-data').textContent.trim()), c => c.charCodeAt(0));
const DATA = JSON.parse(await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
const META = DATA.meta;
const COINS = DATA.coins;
const RUNS = new Map(META.runs.map(r => [r.run_id, r]));
const BY_MINT = new Map(COINS.map(c => [c.mint, c]));
const QUOTES = new Map((META.quotes || []).filter(q => q.mint).map(q => [q.mint, q.label]));
const fmt = new Intl.NumberFormat('en-US');
const state = {variant: ['A','B','C'].includes(new URLSearchParams(location.search).get('variant')) ? new URLSearchParams(location.search).get('variant') : 'A', tab:'coins', query:'', sort:'launch', page:1, selected:null};
const main = document.getElementById('main');
const iconSearch = '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>';
function esc(v){return String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function short(v,n=5){return v ? `${String(v).slice(0,n)}…${String(v).slice(-4)}` : 'Unavailable';}
function amount(v){const n=Number(v); if(v==null||!Number.isFinite(n))return '—'; if(n===0)return '0'; return n.toLocaleString('en-US',{maximumFractionDigits:n<1?4:n<100?2:0});}
function clock(v){if(!v)return '—';return new Date(v).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function date(v){if(!v)return '—';return new Date(v).toLocaleDateString('en-US',{timeZone:'UTC',month:'short',day:'numeric'});}
function duration(v){if(v==null||!Number.isFinite(v))return '—';if(v<1)return '<1s';return v<60?`${Math.floor(v)}s`:`${Math.floor(v/60)}m ${Math.floor(v%60)}s`;}
function runNumber(id){return Number(String(id).split('-')[1]);}
function count(c){return (c.events.buy||0)+(c.events.sell||0);}
function title(c){return c.symbol || c.name || short(c.mint);}
function nameCell(c){return `<div class="coin-cell"><span class="coin-icon" aria-hidden="true">${esc((c.symbol||c.name||c.mint).slice(0,2).toUpperCase())}</span><div><button class="coin-name" data-mint="${esc(c.mint)}" title="Open ${esc(c.name||c.symbol||c.mint)}">${esc(title(c))}</button><div class="mint-short">${esc(short(c.mint,7))}</div></div></div>`;}
function venue(){return '<span class="venue">Pump.fun</span>';}
function quoteLabel(q){const label=QUOTES.get(q);return !q?'Unknown quote':label&&label!=='unknown'?label:short(q);}
function firstVolume(c){return c.volumes?.length===1?c.volumes[0]:null;}
function volumeCell(c,side){const v=firstVolume(c); if(!v)return c.volumes?.length>1?`<span class="muted">${c.volumes.length} currencies</span>`:'<span class="empty-cell">—</span>'; const partial=Number(v[side+'_unavailable']||0)>0; return `<span title="${esc(v[side])} ${esc(quoteLabel(v.quote))}${partial?' (partial)':''}">${partial?'~ ':''}${amount(v[side])} <small class="muted">${esc(quoteLabel(v.quote))}</small></span>`;}
function available(c){return c.runs.reduce((sum,r)=>{if(Number.isFinite(r.available_seconds))return sum+r.available_seconds;const run=RUNS.get(r.run_id);if(!run)return sum;const start=Math.max(Date.parse(run.started_at),Date.parse(c.launch_at||r.first_seen));const end=Date.parse(run.stopped_at);return sum+Math.max(0,(end-start)/1000);},0);}
function runChips(c){return c.runs.map(r=>`<span class="run-chip">R${runNumber(r.run_id)}</span>`).join(' ');}
function resultSet(){const q=state.query.toLowerCase().trim();return COINS.filter(c=>!q||[c.mint,c.name,c.symbol,c.origin].some(s=>String(s||'').toLowerCase().includes(q))).sort((a,b)=>{if(state.sort==='launch')return Number(Boolean(b.launch_at))-Number(Boolean(a.launch_at))||count(b)-count(a)||a.mint.localeCompare(b.mint);if(state.sort==='activity')return count(b)-count(a)||a.mint.localeCompare(b.mint);if(state.sort==='name')return title(a).localeCompare(title(b));return String(a.first_seen||'').localeCompare(String(b.first_seen||''));});}
function pageSize(){return state.variant==='B'?12:state.variant==='C'?16:25;}
function toolbar(results){return `<div class="toolbar"><div class="toolbar-left"><label class="search">${iconSearch}<input id="coin-search" aria-label="Find a coin by name or mint" placeholder="Find a coin by name or mint" value="${esc(state.query)}"></label>${state.query?'<button class="button quiet" data-clear-search>Clear</button>':''}</div><div class="toolbar-right"><span class="result-caption">${fmt.format(results.length)} of ${fmt.format(COINS.length)} coins</span><label class="sort-label" for="sort">Order</label><select id="sort" aria-label="Order coins"><option value="launch" ${state.sort==='launch'?'selected':''}>Captured launches first</option><option value="activity" ${state.sort==='activity'?'selected':''}>Most recorded trades</option><option value="name" ${state.sort==='name'?'selected':''}>Coin name</option><option value="time" ${state.sort==='time'?'selected':''}>First observation</option></select></div></div>`;}
function pager(results){const size=pageSize(),pages=Math.max(1,Math.ceil(results.length/size)),start=(state.page-1)*size;return `<div class="pagination"><span>${results.length?`${fmt.format(start+1)}–${fmt.format(Math.min(start+size,results.length))}`:'0'} of ${fmt.format(results.length)} coins</span><div class="pager-buttons"><button class="button" data-page="${state.page-1}" ${state.page<=1?'disabled':''}>Previous</button><span>${state.page} / ${pages}</span><button class="button" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>Next</button></div></div>`;}
function table(coins,offset=0){return `<p class="mobile-hint">Swipe the table sideways for more columns. Tap a coin for details.</p><div class="table-shell coin-table-shell"><table class="coin-table"><thead><tr><th class="row-index">#</th><th>Coin / mint</th><th>Launch origin</th><th>Recordings</th><th>Creation observed · UTC</th><th class="right">Time to cutoff</th><th class="right">Trades</th><th class="right">Buy volume</th><th class="right">Sell volume</th><th>Buy / sell count</th></tr></thead><tbody>${coins.map((c,i)=>{const total=count(c),ratio=total?(c.events.buy/total)*100:0;const seconds=available(c);return `<tr class="${state.selected===c.mint?'selected':''}"><td class="row-index">${offset+i+1}</td><td>${nameCell(c)}</td><td>${venue(c)}</td><td>${runChips(c)}</td><td>${c.launch_at?`${date(c.launch_at)} <span class="mono">${clock(c.launch_at)}</span>`:'<span class="empty-cell">Not captured</span>'}</td><td class="right ${c.launch_at&&seconds<60?'duration-short':''}" title="Recording time available after creation or first observation; gaps are not deducted">${duration(seconds)}${c.runs.length>1?`<span class="duration-sub">${c.runs.length} separate windows</span>`:''}</td><td class="right">${fmt.format(total)}</td><td class="right">${volumeCell(c,'buy')}</td><td class="right">${volumeCell(c,'sell')}</td><td><div class="mini-track" aria-hidden="true"><i style="width:${ratio}%"></i><b style="width:${total?100-ratio:0}%"></b></div><div class="duration-sub"><span class="buy-text">${fmt.format(c.events.buy||0)}</span> / <span class="sell-text">${fmt.format(c.events.sell||0)}</span></div></td></tr>`;}).join('')}</tbody></table></div><p class="print-only">Print sample: up to 16 rows from this page. The HTML contains all ${fmt.format(COINS.length)} coins, with search and pagination. No source records were excluded.</p>`;}
function bestSeries(c,runId,quote){let list=c.series||[];if(runId)list=list.filter(s=>s.run_id===runId);if(quote)list=list.filter(s=>s.quote===quote);return list[0]||null;}
function chart(c,s,compact=false){if(!s||!s.points?.length)return `<div class="chart-empty">No matched trade quantities to plot.<br><small>${count(c)?'Trade events may still be present in the records.':'No buys or sells recorded in this selection.'}</small></div>`;const w=compact?340:365,h=compact?125:175,l=43,r=8,t=15,b=28;const points=s.points.filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.buy)&&Number.isFinite(p.sell));if(!points.length)return '<div class="chart-empty">Chart unavailable</div>';let buy=0,sell=0;const observed=c.runs.find(r=>r.run_id===s.run_id);const end=observed?Math.max(0,(Date.parse(observed.last_seen)-Date.parse(s.anchor))/1000):Infinity;const cumulative=[{t:0,buy:0,sell:0},...points.map(p=>({t:Math.min(p.t+(s.bin_width_seconds||0),end),buy:buy+=p.buy,sell:sell+=p.sell}))];let xmax=Math.max(1,...cumulative.map(p=>p.t));let ymax=Math.max(0.0001,...cumulative.flatMap(p=>[p.buy,p.sell]));const x=v=>l+(v/xmax)*(w-l-r),y=v=>h-b-(v/ymax)*(h-t-b);const path=side=>cumulative.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)},${y(p[side]).toFixed(2)}`).join(' ');const grid=[0,.5,1].map(f=>`<line class="grid" x1="${l}" y1="${y(ymax*f)}" x2="${w-r}" y2="${y(ymax*f)}"/><text x="${l-7}" y="${y(ymax*f)+3}" text-anchor="end">${amount(ymax*f)}</text>`).join('');const markers=cumulative.length===1?`<circle cx="${x(cumulative[0].t)}" cy="${y(cumulative[0].buy)}" r="3" fill="#176348"/><circle cx="${x(cumulative[0].t)}" cy="${y(cumulative[0].sell)}" r="3" fill="#ad4863"/>`:'';return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Cumulative recorded buy and sell volume in ${esc(quoteLabel(s.quote))}, recording ${runNumber(s.run_id)}"><title>Cumulative recorded volume. ${quoteLabel(s.quote)}. Recording ${runNumber(s.run_id)}. Approximate chart bins.</title>${grid}<path class="line" d="${path('buy')}"/><path class="line sell" d="${path('sell')}"/>${markers}<text x="${l}" y="${h-7}">0s</text><text x="${w-r}" y="${h-7}" text-anchor="end">${duration(xmax)}</text></svg>`;}
function atlas(results,selected){return `<div class="atlas-intro"><div class="atlas-summary"><div><h2>Read the shape of each recording.</h2><p>The same Pump.fun launches, with recorded trading activity brought forward. Each chart shows one recording and one currency.</p></div><div class="atlas-counts"><div><strong>${META.launch_mints}</strong><small>Pump.fun launches</small></div><div><strong>${fmt.format(META.raw_records)}</strong><small>matching raw records</small></div></div></div><div class="legend-block"><div class="legend"><span><i></i>Cumulative buys</span><span><i class="sell"></i>Cumulative sells</span></div><span>Charts stop with the observations. No future path is implied.</span><span>Axes scale independently; compare the amounts as well as the shapes.</span></div></div>${toolbar(results)}<div class="atlas-grid">${selected.map(c=>{const s=bestSeries(c);return `<article class="atlas-coin"><div class="atlas-coin-heading">${nameCell(c)}${venue(c)}</div><div class="atlas-meta"><span><b>${fmt.format(count(c))}</b> trades</span><span><b>${duration(available(c))}</b> to cutoff</span><span>${s?`R${runNumber(s.run_id)} · ${esc(quoteLabel(s.quote))}`:'No volume series'}</span></div>${chart(c,s,true)}<p class="chart-note">${s?.anchor_mode==='since_creation'?'Time since captured creation':'Time since first observation in this recording'}${s?` · R${runNumber(s.run_id)}`:''}${c.series?.length>1?`<br>Chart 1 of ${c.series.length} · ${c.volumes.length} ${c.volumes.length===1?'currency':'currencies'}`:''}</p><button class="inspect" data-mint="${esc(c.mint)}">${c.series?.length>1?`View all ${c.series.length} charts &amp; records`:'Inspect records'} &rarr;</button></article>`;}).join('')}</div>${pager(results)}`;}
function bars(){const max=Math.max(...META.runs.map(r=>r.raw_records));return `<div class="recording-bars">${META.runs.map(r=>`<div class="recording-line"><span>Run ${String(runNumber(r.run_id)).padStart(2,'0')}</span><div class="bar"><i style="width:${r.raw_records/max*100}%"></i></div><span class="number">${fmt.format(r.raw_records)}</span></div>`).join('')}</div>`;}
function report(results,selected){return `<div class="report-layout"><aside class="report-outline"><h3>In this report</h3><a href="#report-overview">The recorded batch</a><a href="#report-volume">Records by run</a><a href="#report-table">The coin inventory</a><div class="outline-note">A reading-first layout.<br>Use Print / PDF for a static copy.<br><br>All measurements describe these recordings only.</div></aside><article class="report-paper"><h2 id="report-overview">A closer look at<br>the Pump.fun recordings.</h2><p class="report-byline">${date(META.runs[0].started_at)}–${date(META.runs.at(-1).started_at)}, 2026 · Four separate recordings · Pump.fun only</p><p class="report-deck">The recordings contain ${fmt.format(COINS.length)} Pump.fun launches whose creation was explicitly captured. No other launch provider remains in this report.</p><div class="report-facts"><div><strong>${fmt.format(META.raw_records)}</strong><p>matching raw records across four runs</p></div><div><strong>30 minutes</strong><p>recording time, with gaps between runs</p></div></div><section id="report-volume" class="report-section"><h3>The recordings are separate windows.</h3><p>Bar lengths show Pump.fun raw record counts, not volume or market performance. The gaps between recording dates are not observed market time.</p>${bars()}</section><section id="report-table" class="report-section"><h3>The Pump.fun coin inventory</h3><p>Every row is anchored to an explicit Pump.fun creation event. No trade count or volume has been used to screen these launches.</p>${toolbar(results)}${table(selected,(state.page-1)*pageSize())}${pager(results)}</section></article></div>`;}
function runsView(){return `<div class="toolbar"><div><h2>Four capture runs</h2><p class="scope-note">One shared cutoff per run. Coins discovered near the end have shorter observation windows. Times below are UTC.</p></div></div><div class="table-shell"><table class="run-table"><thead><tr><th>Recording</th><th>Started / ended · UTC</th><th>Duration</th><th>Raw records</th><th>Normalized records</th><th>Recorded state</th><th>Gap notes</th></tr></thead><tbody>${META.runs.map(r=>`<tr><td><strong>Run ${String(runNumber(r.run_id)).padStart(2,'0')}</strong><small>${esc(r.run_id)}</small></td><td>${date(r.started_at)} ${clock(r.started_at)}<small>Ended ${clock(r.stopped_at)}</small></td><td>${r.duration_ms/60000} min</td><td>${fmt.format(r.raw_records)}</td><td>${fmt.format(r.normalized_records)}</td><td>Timer ended<small>${esc(r.status)}</small></td><td>${(r.reliability_gaps||[]).length?`${r.reliability_gaps.length} gap/reliability note(s)`:'No gap row recorded'}<small>Does not certify complete delivery</small></td></tr>`).join('')}</tbody></table></div><div class="about" style="margin-top:24px"><h3>One batch does not mean one continuous recording</h3><p>These four recordings are grouped for inspection. Their individual run IDs and capture windows remain intact. A future report can use the same display for one run or a chosen group of runs.</p></div>`;}
function aboutView(){return `<article class="about"><h2>A Pump.fun-only preview of the Pump.fun payloads</h2><p>This file is for choosing the deliverable's layout. It uses real local recordings. No risk score, winner label or historical lookup has been applied.</p><dl><dt>What is included</dt><dd>All ${fmt.format(COINS.length)} mints have an explicit creation event whose provider pool is exactly “pump.” Meteora and unknown-origin mints are excluded.</dd><dt>What is summarized</dt><dd>Coin-level event counts and matched raw trade quantities for that Pump.fun universe. Raw frames can contain several events; raw record counts and trade counts are different quantities. This compact file does not embed the full ${META.bytes_total_gib} GiB source corpus.</dd><dt>Time to cutoff</dt><dd>The time from captured creation, or first observation, to that recording's cutoff, using the provider timestamp when present and receipt time otherwise. For coins appearing in multiple recordings it sums separate windows. Known interruptions are not deducted; it is not a guarantee of continuous observation.</dd><dt>Volume</dt><dd>Recorded buy and sell quote quantities, kept separate by currency. SOL and USDC are not added together. Values on screen are rounded; coin details expose exact stored totals. A missing quantity remains unavailable.</dd><dt>Charts</dt><dd>Small, approximate bins of recorded trade quantities, presented cumulatively. Each chart uses one run and one quote currency. Individual scales differ. Blank space after observations is not zero activity.</dd><dt>Origin</dt><dd>Every row requires a captured creation event with pool “pump.” A mint suffix or later trade venue is never used as launch-provider proof. Later events remain attached to an accepted Pump.fun mint after migration.</dd><dt>Evidence examples</dt><dd>A small set of source examples with run ID and raw sequence. They are examples, not the entire event history. Original source records remain unchanged.</dd><dt>What remains unknown</dt><dd>Later outcomes, confirmed bundle membership, beneficial wallet ownership and whether a trade would have been profitable.</dd><dt>Local file</dt><dd>This preview works without a server or external libraries. Search, layout changes and inspection stay in your browser. It does not transmit data.</dd></dl></article>`;}
function render(){document.body.dataset.variant=state.variant;document.querySelectorAll('[data-variant]').forEach(b=>{b.classList.toggle('selected',b.dataset.variant===state.variant);b.setAttribute('aria-pressed',String(b.dataset.variant===state.variant));});document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-current',b.dataset.tab===state.tab?'page':'false');});if(state.tab==='runs'){main.innerHTML=runsView();return;}if(state.tab==='about'){main.innerHTML=aboutView();return;}const results=resultSet();state.page=Math.min(state.page,Math.max(1,Math.ceil(results.length/pageSize())));const selected=results.slice((state.page-1)*pageSize(),state.page*pageSize());if(!results.length){main.innerHTML=toolbar(results)+'<div class="empty-search"><h3>No matching coin in this view</h3><p>Try a different name or paste a mint address. The Pump.fun payloadsset is unchanged.</p><button class="button" data-clear-search style="margin-top:18px">Show all coins</button></div>';return;}if(state.variant==='B')main.innerHTML=atlas(results,selected);else if(state.variant==='C')main.innerHTML=report(results,selected);else main.innerHTML=toolbar(results)+`<p class="scope-note">${META.launch_mints} Pump.fun launches · Other launch providers excluded · No analytical screening. Tap a coin for its evidence.</p>`+table(selected,(state.page-1)*pageSize())+pager(results)+`<div class="table-bottom"><span>Search and ordering change this view. The export always includes every coin.</span><span><span class="buy-text">Green: buys</span> · <span class="sell-text">Rose: sells</span> · All times UTC</span></div>`;}
function openDetail(mint){const c=BY_MINT.get(mint);if(!c)return;state.selected=mint;const el=document.getElementById('inspector');const series=bestSeries(c);el.hidden=false;el.innerHTML=`<div class="inspector-top"><span>Source record detail</span><button class="close-detail" aria-label="Close coin details">&times;</button></div>${venue(c)}<h2>${esc(title(c))}</h2><p class="muted" style="font-size:12px;margin:5px 0 9px">${esc(c.name||'Name unavailable in the captured source')}</p><div class="mint-full">${esc(c.mint)}</div><button class="button quiet" data-copy="${esc(c.mint)}" style="padding:9px 0;font-size:11px">Copy mint address</button><dl class="detail-grid"><div><dt>Recorded trades</dt><dd>${fmt.format(count(c))}</dd></div><div><dt>All matched events</dt><dd>${fmt.format(c.events.count)}</dd></div><div><dt>Buy / sell count</dt><dd><span class="buy-text">${fmt.format(c.events.buy)}</span> / <span class="sell-text">${fmt.format(c.events.sell)}</span></dd></div><div><dt>Time to cutoff</dt><dd>${duration(available(c))}</dd></div></dl><p class="chart-note">${c.launch_at?`Creation captured ${date(c.launch_at)}, ${clock(c.launch_at)} UTC.`:'Creation was not captured. This is an observation of an already existing coin.'} ${c.runs.length>1?`${c.runs.length} separate recording windows are represented.`:''}</p><section class="detail-section"><h3>Recorded volume over time</h3>${c.series?.length>1?`<select id="detail-series" aria-label="Choose recording and quote currency" style="width:100%;max-width:none;margin-bottom:12px">${c.series.map((s,i)=>`<option value="${i}">Run ${runNumber(s.run_id)} · ${esc(quoteLabel(s.quote))}</option>`).join('')}</select>`:''}<div id="detail-chart">${detailChart(c,series)}</div></section><section class="detail-section"><h3>Exact matched quote quantities</h3>${c.volumes?.length?c.volumes.map(v=>`<div class="evidence-row"><span>${esc(quoteLabel(v.quote))}<small>${esc(v.quote||'Quote not identified')}</small></span><span style="text-align:right;word-break:break-all;max-width:190px"><span class="buy-text">Buy ${esc(v.buy)}</span><br><span class="sell-text">Sell ${esc(v.sell)}</span>${v.buy_unavailable||v.sell_unavailable?'<small>Some quantities unavailable</small>':''}</span></div>`).join(''):'<p class="chart-note">No matched quantities available.</p>'}</section><section class="detail-section"><h3>Recording windows</h3>${c.runs.map(r=>`<div class="evidence-row"><span>Run ${runNumber(r.run_id)}<small>${date(r.first_seen)} · ${clock(r.first_seen)}–${clock(r.last_seen)} UTC</small></span><span>${fmt.format(r.event_count)} events<small>${r.buy_count+r.sell_count} trades</small></span></div>`).join('')}<p class="chart-note">Event times show first and last recorded observations. The source may have gaps between them.</p></section><section class="detail-section"><h3>Source examples</h3><p class="chart-note">${c.evidence?.length||0} examples, not a complete history. Run and sequence locate the original raw frame.</p>${(c.evidence||[]).map((e,i)=>evidenceCard(e,i)).join('')}</section>`;el.querySelector('.close-detail').focus();}
function evidenceCard(e,i){const q=quoteLabel(e.quote);const fields=[['Quote currency',q],['Price in quote · source',e.price],['Market cap in quote · source',e.market_cap_quote],['Pool token reserve · source',e.pool_token_reserve],['Pool quote reserve · source',e.pool_quote_reserve],['Fee rate · source',e.fee_rate],['Token amount · source',e.token_amount],['Quote amount · source',e.quote_amount],['Trade venue / pool',e.pool],['Transaction signer',e.tx_signer],['Trader',e.trader],['Source location',e.source_ref]];return `<details class="source-example" ${i===0?'open':''}><summary><strong>${esc(e.action)} · ${clock(e.time)} UTC</strong><span>R${runNumber(e.run_id)} / #${esc(e.seq)}</span></summary><p class="chart-note">One recorded event. Quote values are in ${esc(q)}; no USD conversion or later value is inferred.</p><dl class="raw-fields">${fields.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${value==null?'<span class="muted">Not present</span>':esc(value)}</dd></div>`).join('')}</dl></details>`;}
function detailChart(c,s){return `${chart(c,s)}<div class="legend"><span><i></i>Buys</span><span><i class="sell"></i>Sells</span></div><p class="chart-note">${s?`Run ${runNumber(s.run_id)} · ${esc(quoteLabel(s.quote))}. `:''}${s?.anchor_mode==='since_creation'?'Time since captured creation.':'Time since first observation in this recording.'} ${s?.bin_width_seconds?`Up to ${s.bin_width_seconds}s per chart bin. `:''}Approximate cumulative chart; no activity is inferred beyond the recorded points.</p>`;}
function closeDetail(){document.getElementById('inspector').hidden=true;const previous=state.selected;state.selected=null;document.querySelector(`button[data-mint="${CSS.escape(previous||'')}"]`)?.focus();}
function setVariant(v){state.variant=v;state.page=1;state.tab='coins';const url=new URL(location.href);url.searchParams.set('variant',v);try{history.replaceState(null,'',url);}catch{}render();}
function cycle(d){const variants=['A','B','C'];setVariant(variants[(variants.indexOf(state.variant)+d+3)%3]);}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.hidden=false;setTimeout(()=>el.hidden=true,2200);}
function csv(){const safe=v=>{let s=String(v??'');if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Mint','Name','Symbol','Captured launch origin','Creation time UTC','Recordings','Events','Buy events','Sell events','Seconds to cutoff','Quote quantities']];for(const c of COINS)rows.push([c.mint,c.name,c.symbol,c.origin,c.launch_at,c.runs.map(r=>r.run_id).join('; '),c.events.count,c.events.buy,c.events.sell,available(c),JSON.stringify(c.volumes)]);const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='meme-explorer-pumpfun-coins.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(`Exported all ${fmt.format(COINS.length)} coins`);}
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.variant)setVariant(button.dataset.variant);else if(button.dataset.tab){state.tab=button.dataset.tab;render();}else if(button.dataset.mint)openDetail(button.dataset.mint);else if(button.dataset.page){state.page=Number(button.dataset.page);render();}else if(button.hasAttribute('data-clear-search')){state.query='';state.page=1;render();}else if(button.classList.contains('close-detail'))closeDetail();else if(button.dataset.copy){try{await navigator.clipboard.writeText(button.dataset.copy);toast('Mint address copied');}catch{toast('Select the mint address above to copy it.');}}});
document.addEventListener('input',e=>{if(e.target.id==='coin-search'){const value=e.target.value,position=e.target.selectionStart;state.query=value;state.page=1;render();const input=document.getElementById('coin-search');input.focus();input.setSelectionRange(position,position);}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){state.sort=e.target.value;state.page=1;render();}else if(e.target.id==='detail-series'){const c=BY_MINT.get(state.selected);document.getElementById('detail-chart').innerHTML=detailChart(c,c.series[Number(e.target.value)]);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.getElementById('inspector').hidden){closeDetail();return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowLeft'){e.preventDefault();cycle(-1);}if(e.key==='ArrowRight'){e.preventDefault();cycle(1);}});
document.getElementById('previous-variant').onclick=()=>cycle(-1);document.getElementById('next-variant').onclick=()=>cycle(1);document.getElementById('download-csv').onclick=csv;document.getElementById('print').onclick=()=>window.print();
document.getElementById('coin-total').textContent=fmt.format(COINS.length);
document.getElementById('batch-summary').innerHTML=[['4','capture runs'],['30 min','recorded time'],[fmt.format(META.raw_records),'raw records'],[fmt.format(COINS.length),'mint addresses'],[`${META.bytes_total_gib} GiB`,'Pump.fun payloads']].map(([v,l])=>`<div class="summary-item"><strong>${v}</strong><span>${l}</span></div>`).join('');
render();
